public struct SubscriptionSource {
    public var id: UInt16
    /**
     * Clash/mihomo YAML 全文
     */
    public var yaml: String

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(id: UInt16, 
        /**
         * Clash/mihomo YAML 全文
         */yaml: String) {
        self.id = id
        self.yaml = yaml
    }
}



extension SubscriptionSource: Equatable, Hashable {
    public static func ==(lhs: SubscriptionSource, rhs: SubscriptionSource) -> Bool {
        if lhs.id != rhs.id {
            return false
        }
        if lhs.yaml != rhs.yaml {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(id)
        hasher.combine(yaml)
    }
}


